import React from 'react'
import {
  Card,
  CardContent,
  CardDescription,
  CardTitle,
} from "@/components/ui/card"

const HeartLine = () => {
  
  return (
      <div className="flex flex-col min-h-screen">
        <div className="navbar bg-base-100">
          <div className="navbar-start"></div>
          <h1 className="navbar-center text-5xl">Heart Line</h1>
          <div className="navbar-end"></div>
        </div>
        <div className="misc-heading">
          <h1 className="scroll-m-20 text-start text-4xl font-extrabold tracking-tight text-balance">
            We found a great match for you!
          </h1>
        </div>
        <div className='therapist-card'>
          <Card>
            <CardTitle>Dr. Aisha Patel</CardTitle>
            <CardDescription>Dr. Patel creates a supportive environment for exploring patterns and building self-worth.</CardDescription>
            <CardContent>
              <p className="leading-7 [&:not(:first-child)]:mt-6">
                Qualification: Blah Blah Blah Degree
              </p>
              <p className="leading-7 [&:not(:first-child)]:mt-6">
                Approach: Person-Centered, Psychodynamic
              </p>
              <p className="leading-7 [&:not(:first-child)]:mt-6">
                Has helped people with : Relationship Issues, Self-Esteem
              </p>
            </CardContent>
          </Card>
        </div>

        <section className='review-section'>
          <div className='review-headin'>
             <h3 className="scroll-m-20 text-2xl font-semibold tracking-tight">
                Here’s what people had to say:
              </h3>
          </div>
          <Card>
            <CardContent>
              <blockquote className="mt-6 pl-6 italic">
                &quot;Dr. Patel has a way of asking questions that linger in your mind long after the session. 
                Her approach helped me realize how much of my low self-esteem came from childhood dynamics I never fully processed. 
                I feel like I&apos;m finally rewriting my own story.&quot;
              </blockquote>
            </CardContent>
          </Card>
        </section>

      </div>
    );
}

export default HeartLine